from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]


def write(path: str, content: str) -> None:
    target = ROOT / path
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(content, encoding="utf-8")


def replace_once(path: str, old: str, new: str) -> None:
    target = ROOT / path
    text = target.read_text(encoding="utf-8")
    if old not in text:
        raise RuntimeError(f"expected patch anchor missing in {path}: {old[:180]!r}")
    target.write_text(text.replace(old, new, 1), encoding="utf-8")


write(
    "src/sao_mcp/runtime/gm_observation.py",
    '''from __future__ import annotations\n\nfrom dataclasses import asdict\nfrom typing import Any\n\nfrom sao_mcp.domain.models import EntityKind\nfrom sao_mcp.rules.state_authority import authoritative_guild_id\n\n\nVISIBLE_COMBAT_EVENT_PAYLOAD_KEYS = frozenset({\n    "hit",\n    "critical",\n    "parried",\n    "guarded",\n    "evaded",\n    "damage",\n    "sword_skill",\n    "reason",\n    "template_id",\n    "consumed",\n    "status",\n    "status_type",\n    "incoming_id",\n    "destination_id",\n    "actor_ids",\n})\n\n\nclass GMObservationGate:\n    \"\"\"Project only state observable from explicitly named player viewpoints.\n\n    The gate is stateless. It never owns world, actor, quest, guild or knowledge state; all rows are\n    derived from the authoritative runtime at read time. Hidden actor-core plans, world-event\n    occurrences, canonical expectations, threat tables and other omniscient runtime internals have\n    no projection here.\n    \"\"\"\n\n    def __init__(self, runtime) -> None:\n        self.runtime = runtime\n\n    def validate_observer_actor_ids(self, observer_actor_ids: list[str] | tuple[str, ...]) -> tuple[str, ...]:\n        if not isinstance(observer_actor_ids, (list, tuple)) or not observer_actor_ids:\n            raise ValueError("GM observation requires at least one explicit player viewpoint")\n        if any(not isinstance(actor_id, str) or not actor_id for actor_id in observer_actor_ids):\n            raise ValueError("GM observation viewpoint IDs must be non-empty strings")\n        ids = tuple(observer_actor_ids)\n        if len(set(ids)) != len(ids):\n            raise ValueError("GM observation viewpoint IDs must be unique")\n        for actor_id in ids:\n            actor = self.runtime.actors.get(actor_id)\n            if actor is None:\n                raise KeyError(actor_id)\n            if actor.kind is not EntityKind.PLAYER:\n                raise ValueError("GM observation viewpoints must be player actors")\n        return ids\n\n    def current_observer_encounter_ids(self, observer_actor_ids: tuple[str, ...]) -> set[str]:\n        observer_set = set(observer_actor_ids)\n        return {\n            encounter_id\n            for encounter_id, encounter in self.runtime.encounters.items()\n            if observer_set.intersection(encounter.participants)\n        }\n\n    def _self_actor(self, actor_id: str) -> dict[str, Any]:\n        actor = self.runtime.actors[actor_id]\n        return {\n            "actor_id": actor.actor_id,\n            "name": actor.name,\n            "kind": actor.kind.value,\n            "level": actor.level,\n            "hp": actor.hp,\n            "max_hp": actor.max_hp,\n            "alive": actor.alive,\n            "location_id": actor.location_id,\n            "cursor": actor.cursor.value,\n            "col": actor.col,\n            "equipment": dict(actor.equipment),\n            "inventory": [\n                {\n                    "instance_id": item.instance_id,\n                    "template_id": item.template_id,\n                    "quantity": item.quantity,\n                    "durability": item.durability,\n                    "max_durability": item.max_durability,\n                }\n                for item in sorted(actor.inventory.values(), key=lambda row: row.instance_id)\n            ],\n            "statuses": [\n                {\n                    "status_type": status.status_type.value,\n                    "remaining_ms": status.remaining_ms,\n                }\n                for status in actor.statuses\n                if status.remaining_ms > 0\n            ],\n            "committed_until_ms": actor.committed_until_ms,\n            "recovery_until_ms": actor.recovery_until_ms,\n        }\n\n    def _location(self, actor_id: str) -> dict[str, Any] | None:\n        location_id = self.runtime.actors[actor_id].location_id\n        if location_id is None:\n            return None\n        location = self.runtime.world_map.locations[location_id]\n        return {\n            "location_id": location.location_id,\n            "name": location.name,\n            "floor_number": location.floor_number,\n            "zone_kind": location.zone_kind.value,\n            "safe_zone": location.safe_zone,\n            "anti_crystal": location.anti_crystal,\n            "teleport_gate": location.teleport_gate,\n        }\n\n    def _player_name_known(self, observer_id: str, target_id: str) -> bool:\n        if observer_id == target_id:\n            return True\n        belief = self.runtime.belief(observer_id, f"player_identity:{target_id}")\n        return belief is not None\n\n    def _active_encounter_with(self, observer_id: str, target_id: str) -> bool:\n        return any(\n            encounter.active\n            and observer_id in encounter.participants\n            and target_id in encounter.participants\n            for encounter in self.runtime.encounters.values()\n        )\n\n    def _visible_entities(self, observer_id: str) -> list[dict[str, Any]]:\n        actor = self.runtime.actors[observer_id]\n        if actor.location_id is None:\n            return []\n        location_id = actor.location_id\n        rows: list[dict[str, Any]] = []\n        unknown_player_index = 0\n        materialized_npc_ids: set[str] = set()\n\n        for target in sorted(self.runtime.actors.values(), key=lambda row: row.actor_id):\n            if target.actor_id == observer_id or target.location_id != location_id or not target.alive:\n                continue\n            if target.kind is EntityKind.PLAYER:\n                known = self._player_name_known(observer_id, target.actor_id)\n                if known:\n                    rows.append({\n                        "actor_id": target.actor_id,\n                        "display_name": target.name,\n                        "kind": target.kind.value,\n                        "cursor": target.cursor.value,\n                    })\n                else:\n                    unknown_player_index += 1\n                    rows.append({\n                        "scene_ref": f"unknown_player_{unknown_player_index}",\n                        "display_name": "Unknown Player",\n                        "kind": target.kind.value,\n                        "cursor": target.cursor.value,\n                    })\n                continue\n\n            npc_id = target.metadata.get("npc_definition_id")\n            if isinstance(npc_id, str) and npc_id in self.runtime.npcs.definitions:\n                materialized_npc_ids.add(npc_id)\n                rows.append({\n                    "npc_id": npc_id,\n                    "display_name": self.runtime.npcs.definitions[npc_id].name,\n                    "kind": "npc",\n                    "cursor": target.cursor.value,\n                })\n                continue\n\n            if self._active_encounter_with(observer_id, target.actor_id):\n                rows.append({\n                    "actor_id": target.actor_id,\n                    "display_name": target.name,\n                    "kind": target.kind.value,\n                    "cursor": target.cursor.value,\n                })\n\n        for npc_id, definition in sorted(self.runtime.npcs.definitions.items()):\n            if npc_id in materialized_npc_ids:\n                continue\n            if self.runtime.npc_location_id(npc_id) != location_id:\n                continue\n            rows.append({\n                "npc_id": npc_id,\n                "display_name": definition.name,\n                "kind": "npc",\n            })\n        return rows\n\n    def _participant(self, observer_id: str, participant) -> dict[str, Any]:\n        if participant.kind is EntityKind.PLAYER and participant.actor_id != observer_id:\n            display_name = (\n                participant.name\n                if self._player_name_known(observer_id, participant.actor_id)\n                else "Unknown Player"\n            )\n        else:\n            display_name = participant.name\n        return {\n            "actor_id": participant.actor_id,\n            "display_name": display_name,\n            "kind": participant.kind.value,\n            "hp": participant.hp,\n            "max_hp": participant.max_hp,\n            "alive": participant.alive,\n            "cursor": participant.cursor.value,\n            "statuses": [\n                status.status_type.value\n                for status in participant.statuses\n                if status.remaining_ms > 0\n            ],\n        }\n\n    @staticmethod\n    def _event(event) -> dict[str, Any]:\n        payload = {\n            key: value\n            for key, value in event.payload.items()\n            if key in VISIBLE_COMBAT_EVENT_PAYLOAD_KEYS\n        }\n        return {\n            "time_ms": event.time_ms,\n            "event_type": event.event_type,\n            "actor_id": event.actor_id,\n            "target_id": event.target_id,\n            "payload": payload,\n        }\n\n    def _encounters(\n        self,\n        observer_id: str,\n        *,\n        allowed_encounter_ids: set[str],\n        event_offsets: dict[str, int] | None,\n    ) -> dict[str, Any]:\n        rows: dict[str, Any] = {}\n        for encounter_id in sorted(allowed_encounter_ids):\n            encounter = self.runtime.encounters.get(encounter_id)\n            if encounter is None or observer_id not in encounter.participants:\n                continue\n            row = {\n                "encounter_id": encounter_id,\n                "zone_id": encounter.zone_id,\n                "time_ms": encounter.time_ms,\n                "active": encounter.active,\n                "participants": {\n                    actor_id: self._participant(observer_id, participant)\n                    for actor_id, participant in encounter.participants.items()\n                },\n            }\n            if event_offsets is not None:\n                start = event_offsets.get(encounter_id, len(encounter.events))\n                row["recent_events"] = [\n                    self._event(event) for event in encounter.events[start:]\n                ]\n            rows[encounter_id] = row\n        return rows\n\n    def _quest_log(self, observer_id: str) -> dict[str, Any]:\n        active = self.runtime.quests.progress_by_actor.get(observer_id, {})\n        completed = self.runtime.quests.completed_by_actor.get(observer_id, set())\n        return {\n            "active": {quest_id: asdict(progress) for quest_id, progress in sorted(active.items())},\n            "completed_quest_ids": sorted(completed),\n        }\n\n    def _guild(self, observer_id: str) -> dict[str, Any] | None:\n        guild_id = authoritative_guild_id(self.runtime, observer_id)\n        if guild_id is None:\n            return None\n        guild = self.runtime.relationships.guilds[guild_id]\n        return {\n            "guild_id": guild.guild_id,\n            "name": guild.name,\n            "leader_id": guild.leader_id,\n            "member_ids": list(guild.member_ids),\n            "manager_ids": list(guild.manager_ids),\n            "emblem": guild.emblem,\n            "headquarters_location_id": guild.headquarters_location_id,\n        }\n\n    def _relationships(self, observer_id: str) -> dict[str, Any]:\n        marriage = self.runtime.relationships.marriage_for(observer_id)\n        return {\n            "friend_ids": sorted(self.runtime.relationships.friends.get(observer_id, set())),\n            "spouse_id": (\n                next((actor_id for actor_id in marriage.partner_ids if actor_id != observer_id), None)\n                if marriage is not None\n                else None\n            ),\n        }\n\n    def _messages(self, observer_id: str) -> list[dict[str, Any]]:\n        if not hasattr(self.runtime, "message_inbox"):\n            return []\n        return [\n            {\n                "message_id": message.message_id,\n                "sender_id": message.sender_id,\n                "channel": message.channel.value,\n                "text": message.text,\n                "sent_at_ms": message.sent_at_ms,\n                "read_at_ms": message.read_at_ms,\n            }\n            for message in self.runtime.message_inbox(observer_id)\n        ]\n\n    def observe(\n        self,\n        observer_actor_ids: list[str] | tuple[str, ...],\n        *,\n        event_offsets: dict[str, int] | None = None,\n        additional_encounter_ids: set[str] | None = None,\n    ) -> dict[str, Any]:\n        observer_ids = self.validate_observer_actor_ids(observer_actor_ids)\n        current_encounters = self.current_observer_encounter_ids(observer_ids)\n        allowed_encounters = set(current_encounters)\n        if additional_encounter_ids:\n            allowed_encounters.update(additional_encounter_ids)\n        viewpoints = {}\n        for observer_id in observer_ids:\n            viewpoints[observer_id] = {\n                "observer": self._self_actor(observer_id),\n                "location": self._location(observer_id),\n                "visible_entities": self._visible_entities(observer_id),\n                "knowledge": self.runtime.knowledge_state(observer_id),\n                "quest_log": self._quest_log(observer_id),\n                "guild": self._guild(observer_id),\n                "relationships": self._relationships(observer_id),\n                "messages": self._messages(observer_id),\n                "encounters": self._encounters(\n                    observer_id,\n                    allowed_encounter_ids=allowed_encounters,\n                    event_offsets=event_offsets,\n                ),\n            }\n        return {\n            "world_now_ms": self.runtime.world.now_ms,\n            "observer_actor_ids": list(observer_ids),\n            "viewpoints": viewpoints,\n        }\n''',
)

# GM turn: remove ungated projections and make viewpoint explicit.
path = "src/sao_mcp/runtime/gm_turn.py"
target = ROOT / path
text = target.read_text(encoding="utf-8")
text = text.replace("from dataclasses import asdict, is_dataclass\nfrom enum import Enum\n", "")
text = text.replace(
    "from sao_mcp.domain.models import DefenseMode\n",
    "from sao_mcp.domain.models import DefenseMode\nfrom sao_mcp.runtime.gm_observation import GMObservationGate\n",
)
plain_start = text.index("\ndef _plain(value: Any) -> Any:\n")
class_start = text.index("\n\nclass GMTurnExecutor:\n")
text = text[:plain_start] + text[class_start:]
text = text.replace(
    "    def __init__(self, runtime) -> None:\n        self.runtime = runtime\n",
    "    def __init__(self, runtime) -> None:\n"
    "        self.runtime = runtime\n"
    "        self.observation_gate = GMObservationGate(runtime)\n",
)
helpers_start = text.index("\n    @staticmethod\n    def _actor_ids(")
text = text[:helpers_start] + '''\n    def observe(self, observer_actor_ids: list[str] | tuple[str, ...]) -> dict[str, Any]:\n        return self.observation_gate.observe(observer_actor_ids)\n\n    def execute(\n        self,\n        actions: list[dict[str, Any]],\n        *,\n        observer_actor_ids: list[str] | tuple[str, ...],\n        world_tick_ms: int = 0,\n    ) -> dict[str, Any]:\n        self._validate_plan(actions, world_tick_ms)\n        observer_ids = self.observation_gate.validate_observer_actor_ids(observer_actor_ids)\n        runtime = self.runtime\n        world_before = runtime.world.now_ms\n        event_counts = {\n            encounter_id: len(encounter.events)\n            for encounter_id, encounter in runtime.encounters.items()\n        }\n        encounter_ids_before = self.observation_gate.current_observer_encounter_ids(observer_ids)\n\n        for action in actions:\n            self._execute_action(action)\n\n        activated = runtime.advance_world(world_tick_ms) if world_tick_ms else []\n        encounter_ids_after = self.observation_gate.current_observer_encounter_ids(observer_ids)\n        observation = self.observation_gate.observe(\n            observer_ids,\n            event_offsets=event_counts,\n            additional_encounter_ids=encounter_ids_before | encounter_ids_after,\n        )\n        return {\n            "world_time_before_ms": world_before,\n            "world_time_after_ms": runtime.world.now_ms,\n            "final_world_tick_ms": world_tick_ms,\n            "activated_floor_gates": list(activated),\n            "actions_executed": len(actions),\n            "observation": observation,\n        }\n'''
target.write_text(text, encoding="utf-8")

# Replace the GM MCP surface with gated observation only.
write(
    "src/sao_mcp/server_gm.py",
    '''from __future__ import annotations\n\nimport json\nfrom dataclasses import asdict, is_dataclass\nfrom enum import Enum\nfrom typing import Any\n\n\ndef _default(value: Any):\n    if is_dataclass(value):\n        return asdict(value)\n    if isinstance(value, Enum):\n        return value.value\n    if isinstance(value, set):\n        return sorted(value)\n    raise TypeError(type(value).__name__)\n\n\ndef _json(value: Any) -> str:\n    return json.dumps(value, ensure_ascii=False, default=_default)\n\n\ndef register_gm_tools(mcp, gm_turn_executor) -> None:\n    @mcp.tool()\n    def execute_gm_turn(\n        actions: list[dict[str, Any]],\n        observer_actor_ids: list[str],\n        world_tick_ms: int = 0,\n    ) -> str:\n        \"\"\"Execute a structured GM action plan and return only player-viewpoint-gated state.\n\n        The action plan still resolves through authoritative runtime mechanics. The returned packet does\n        not expose raw action results, NPC actor-core plans, guild strategy internals, world-event\n        occurrences, canonical timeline expectations or another entity's private knowledge.\n        \"\"\"\n        return _json(\n            gm_turn_executor.execute(\n                actions,\n                observer_actor_ids=observer_actor_ids,\n                world_tick_ms=world_tick_ms,\n            )\n        )\n\n    @mcp.tool()\n    def get_gm_turn_action_contract() -> str:\n        \"\"\"Return the exact structured action names accepted by execute_gm_turn.\"\"\"\n        return _json({"actions": gm_turn_executor.supported_actions()})\n\n    @mcp.tool()\n    def get_gm_observation(observer_actor_ids: list[str]) -> str:\n        \"\"\"Return current observable state for explicit player viewpoints only.\"\"\"\n        return _json(gm_turn_executor.observe(observer_actor_ids))\n''',
)

# Rewrite GM turn tests around the gate.
write(
    "tests/test_gm_turn.py",
    '''import pytest\n\nfrom sao_mcp.runtime.gm_turn import GMTurnExecutor\nfrom sao_mcp.runtime.social_communication_runtime import SocialCommunicationAincradRuntime\n\n\ndef test_gm_turn_validates_entire_action_shape_before_any_mechanical_mutation():\n    runtime = SocialCommunicationAincradRuntime(seed=301)\n    actor = runtime.create_character("TurnShape", level=8)\n    executor = GMTurnExecutor(runtime)\n    started = runtime.world.now_ms\n    origin = actor.location_id\n\n    with pytest.raises(ValueError, match="unsupported GM turn action"):\n        executor.execute(\n            [\n                {"op": "travel", "actor_id": actor.actor_id, "destination_id": "floor_1_west_field"},\n                {"op": "invent_a_result", "actor_id": actor.actor_id},\n            ],\n            observer_actor_ids=[actor.actor_id],\n        )\n\n    assert runtime.world.now_ms == started\n    assert actor.location_id == origin\n\n\ndef test_gm_turn_returns_only_gated_observation_not_raw_resolution_or_hidden_agendas():\n    runtime = SocialCommunicationAincradRuntime(seed=303)\n    actor = runtime.create_character("TurnRunner", level=8)\n    executor = GMTurnExecutor(runtime)\n\n    exploration = executor.execute(\n        [\n            {"op": "travel", "actor_id": actor.actor_id, "destination_id": "floor_1_west_field"},\n            {"op": "travel", "actor_id": actor.actor_id, "destination_id": "floor_1_tolbana"},\n        ],\n        observer_actor_ids=[actor.actor_id],\n        world_tick_ms=1_000,\n    )\n    assert exploration["world_time_after_ms"] - exploration["world_time_before_ms"] == 54 * 60_000 + 1_000\n    assert exploration["actions_executed"] == 2\n    assert "steps" not in exploration\n    assert "actors" not in exploration\n    assert "npc_agendas" not in exploration\n    assert "guild_agendas" not in exploration\n    viewpoint = exploration["observation"]["viewpoints"][actor.actor_id]\n    assert viewpoint["observer"]["location_id"] == "floor_1_tolbana"\n\n    actor.location_id = "floor_1_west_field"\n    actor.skill_proficiencies["one_hand_sword"] = 1000.0\n    monster = runtime.create_training_monster(level=4)\n    monster.evasion = 0\n    encounter = runtime.start_encounter([actor.actor_id, monster.actor_id], zone_id="floor_1_west_field")\n    encounter.positions[actor.actor_id] = (0.0, 0.0)\n    encounter.positions[monster.actor_id] = (1.0, 0.0)\n\n    combat = executor.execute(\n        [{\n            "op": "timeline_attack",\n            "encounter_id": encounter.encounter_id,\n            "attacker_id": actor.actor_id,\n            "target_id": monster.actor_id,\n            "defense": "none",\n            "seed": 1,\n        }],\n        observer_actor_ids=[actor.actor_id],\n    )\n    encounter_row = combat["observation"]["viewpoints"][actor.actor_id]["encounters"][encounter.encounter_id]\n    assert encounter_row["recent_events"]\n    attack = next(row for row in encounter_row["recent_events"] if row["event_type"] == "attack")\n    assert "damage" in attack["payload"]\n    assert "hit_chance" not in attack["payload"]\n    assert "threat_generated" not in attack["payload"]\n    assert "weapon_durability" not in attack["payload"]\n''',
)

write(
    "tests/test_gm_observation_gate.py",
    '''import pytest\n\nfrom sao_mcp.runtime.gm_observation import GMObservationGate\nfrom sao_mcp.runtime.gm_turn import GMTurnExecutor\nfrom sao_mcp.runtime.social_communication_runtime import SocialCommunicationAincradRuntime\n\n\nTOWN = "floor_1_town_of_beginnings"\nHORUNKA = "floor_1_horunka"\nWEST = "floor_1_west_field"\n\n\ndef test_gate_requires_explicit_unique_player_viewpoints():\n    runtime = SocialCommunicationAincradRuntime(seed=1701)\n    player = runtime.create_character("Player")\n    gate = GMObservationGate(runtime)\n    with pytest.raises(ValueError, match="at least one explicit player viewpoint"):\n        gate.observe([])\n    with pytest.raises(ValueError, match="unique"):\n        gate.observe([player.actor_id, player.actor_id])\n    with pytest.raises(KeyError):\n        gate.observe(["missing"])\n\n\ndef test_remote_private_state_and_other_entities_knowledge_do_not_enter_player_packet():\n    runtime = SocialCommunicationAincradRuntime(seed=1702)\n    player = runtime.create_character("Observer")\n    remote = runtime.create_character("Remote")\n    remote.location_id = HORUNKA\n    runtime.record_observation(remote.actor_id, "private:remote", "secret", observation_location_id=HORUNKA)\n    runtime.set_npc_goal("npc_tutorial_instructor", "hidden:goal", WEST, priority=999)\n    gate = GMObservationGate(runtime)\n    packet = gate.observe([player.actor_id])\n    view = packet["viewpoints"][player.actor_id]\n    dumped = repr(packet)\n    assert "private:remote" not in dumped\n    assert "hidden:goal" not in dumped\n    assert "long_term_goals" not in dumped\n    assert "short_term_plan" not in dumped\n    assert "world_events" not in dumped\n    assert remote.actor_id not in repr(view["visible_entities"])\n\n\ndef test_colocated_unknown_player_has_no_stable_identity_until_observed_identity_fact_exists():\n    runtime = SocialCommunicationAincradRuntime(seed=1703)\n    observer = runtime.create_character("Observer")\n    stranger = runtime.create_character("Stranger")\n    gate = GMObservationGate(runtime)\n    before = gate.observe([observer.actor_id])["viewpoints"][observer.actor_id]["visible_entities"]\n    unknown = next(row for row in before if row.get("display_name") == "Unknown Player")\n    assert "actor_id" not in unknown\n    assert unknown["scene_ref"].startswith("unknown_player_")\n\n    runtime.learn_player_identity(observer.actor_id, stranger.actor_id)\n    after = gate.observe([observer.actor_id])["viewpoints"][observer.actor_id]["visible_entities"]\n    known = next(row for row in after if row.get("actor_id") == stranger.actor_id)\n    assert known["display_name"] == "Stranger"\n\n\ndef test_gate_uses_observers_actual_belief_without_substituting_runtime_truth():\n    runtime = SocialCommunicationAincradRuntime(seed=1704)\n    observer = runtime.create_character("Observer")\n    runtime.record_observation(\n        observer.actor_id,\n        "rumor:boss_state",\n        {"alive": False},\n        observation_location_id=TOWN,\n        confidence=0.55,\n    )\n    packet = GMObservationGate(runtime).observe([observer.actor_id])\n    fact = packet["viewpoints"][observer.actor_id]["knowledge"]["facts"]["rumor:boss_state"]\n    assert fact["value"] == {"alive": False}\n    assert fact["confidence"] == 0.55\n\n\ndef test_hidden_encounter_is_not_visible_to_unrelated_viewpoint():\n    runtime = SocialCommunicationAincradRuntime(seed=1705)\n    observer = runtime.create_character("Observer")\n    a = runtime.create_character("A")\n    b = runtime.create_character("B")\n    a.location_id = WEST\n    b.location_id = WEST\n    encounter = runtime.start_encounter([a.actor_id, b.actor_id], zone_id=WEST)\n    packet = GMObservationGate(runtime).observe([observer.actor_id])\n    assert encounter.encounter_id not in packet["viewpoints"][observer.actor_id]["encounters"]\n\n\ndef test_player_can_see_own_ui_state_but_not_guild_strategy_resources():\n    runtime = SocialCommunicationAincradRuntime(seed=1706)\n    leader = runtime.create_character("Leader")\n    member = runtime.create_character("Member")\n    guild = runtime.create_guild(leader.actor_id, "Visible Roster")\n    invite = runtime.invite_to_guild(guild.guild_id, leader.actor_id, member.actor_id)\n    runtime.accept_guild_invite(invite.invite_id, member.actor_id)\n    guild.vault_col = 99999\n    runtime.set_guild_strategy_goal(\n        guild.guild_id, leader.actor_id, "secret_strategy", WEST, auto_dispatch=False\n    )\n    packet = GMObservationGate(runtime).observe([leader.actor_id])\n    view = packet["viewpoints"][leader.actor_id]\n    assert view["observer"]["col"] == leader.col\n    assert view["guild"]["member_ids"] == guild.member_ids\n    dumped = repr(view)\n    assert "99999" not in dumped\n    assert "secret_strategy" not in dumped\n    assert "vault_col" not in dumped\n    assert "strategic_goals" not in dumped\n''',
)

write(
    "tests/test_gm_observation_authority.py",
    '''import ast\nfrom pathlib import Path\n\n\nROOT = Path(__file__).resolve().parents[1]\n\n\ndef test_server_gm_exposes_only_gated_observation_and_action_execution_surfaces():\n    source = (ROOT / "src/sao_mcp/server_gm.py").read_text(encoding="utf-8")\n    assert "def get_gm_observation" in source\n    assert "observer_actor_ids" in source\n    for forbidden in (\n        "get_npc_agenda",\n        "get_npc_actor_core",\n        "get_npc_scheduler",\n        "get_guild_agenda",\n        "get_guild_operation",\n        "get_entity_knowledge",\n        "get_entity_knowledge_history",\n        "get_knowledge_event_chain",\n        "get_world_event_state",\n        "get_world_event_history",\n        "get_canonical_timeline_profile",\n        "set_canonical_timeline_profile",\n    ):\n        assert f"def {forbidden}" not in source\n\n\ndef test_gm_turn_has_no_direct_hidden_projection_calls_after_execution():\n    source = (ROOT / "src/sao_mcp/runtime/gm_turn.py").read_text(encoding="utf-8")\n    for forbidden in (\n        "npc_agenda_state(",\n        "npc_actor_core_state(",\n        "npc_scheduler_state(",\n        "guild_agenda_state(",\n        "guild_operation_state(",\n        "knowledge_state(",\n        "world_event_state(",\n        "canonical_timeline_state(",\n    ):\n        assert forbidden not in source\n    assert "GMObservationGate" in source\n\n\ndef test_observation_gate_does_not_read_hidden_autonomy_event_or_canon_authorities():\n    path = ROOT / "src/sao_mcp/runtime/gm_observation.py"\n    tree = ast.parse(path.read_text(encoding="utf-8"), filename=str(path))\n    forbidden = {\n        "npc_actor_cores",\n        "npc_agendas",\n        "npc_schedulers",\n        "guild_strategic_goals",\n        "guild_operations",\n        "world_events",\n        "canonical_timeline",\n        "monster_ecology",\n        "regional_markets",\n        "social_deliveries",\n    }\n    violations = []\n    for node in ast.walk(tree):\n        if isinstance(node, ast.Attribute) and node.attr in forbidden:\n            violations.append((node.lineno, node.attr))\n    assert violations == []\n\n\ndef test_observation_gate_is_stateless_projection_not_persistence_authority():\n    source = (ROOT / "src/sao_mcp/runtime/gm_observation.py").read_text(encoding="utf-8")\n    assert "dump_state" not in source\n    assert "load_state" not in source\n    assert "save" not in source.lower()\n    persistence = (ROOT / "src/sao_mcp/runtime/persistence.py").read_text(encoding="utf-8")\n    assert "gm_observation_state" not in persistence\n''',
)
